/// <reference types="node" />
import { readdirSync, readFileSync } from 'node:fs';
import { fileURLToPath } from 'node:url';
import { describe, expect, it } from 'vite-plus/test';

// Spec 001, R8 (D-093): no component formats money or dates on its own. Only the helpers
// may call Intl or a formatting library; everything else goes through them.
const root = fileURLToPath(new URL('../../resources/js', import.meta.url));

// Each exclusion says why.
const excludedFolders: Record<string, string> = {
    'components/ui/': 'shadcn-vue vendor code',
    'actions/': 'generated by Wayfinder, not in git',
    'routes/': 'generated by Wayfinder, not in git',
    'wayfinder/': 'generated by Wayfinder, not in git',
};

// The helpers of spec 001, R8: the only files allowed to format.
const formattingHelpers = ['lib/dates.ts', 'lib/money.ts'];

const formatting = new RegExp(
    [
        String.raw`\bIntl\.(?:NumberFormat|DateTimeFormat|RelativeTimeFormat)\b`,
        String.raw`\.toLocale(?:Date|Time)?String\(`,
        String.raw`from ['"](?:date-fns|dayjs|moment|numeral)(?:/[^'"]*)?['"]`,
    ].join('|'),
    'u',
);

const scannedFiles = (
    readdirSync(root, { recursive: true, encoding: 'utf8' }) as string[]
)
    .map((path) => path.replaceAll('\\', '/'))
    .filter((path) => path.endsWith('.vue') || path.endsWith('.ts'))
    .filter(
        (path) =>
            !Object.keys(excludedFolders).some((dir) => path.startsWith(dir)),
    )
    .filter((path) => !formattingHelpers.includes(path))
    .sort();

describe('money and date formatting outside the spec 001 helpers', () => {
    it('scans the app code and skips the helpers and the excluded folders', () => {
        expect(scannedFiles).toContain('pages/accounts/Index.vue');
        expect(scannedFiles).not.toContain('lib/money.ts');
        expect(scannedFiles).not.toContain('lib/dates.ts');
        expect(
            scannedFiles.filter((path) =>
                Object.keys(excludedFolders).some((dir) =>
                    path.startsWith(dir),
                ),
            ),
        ).toEqual([]);
    });

    it('finds no Intl formatter, toLocale*String() or formatting library', () => {
        const offenders = scannedFiles.filter((path) =>
            formatting.test(readFileSync(`${root}/${path}`, 'utf8')),
        );

        expect(
            offenders,
            'Use formatMoney or formatRelativeDate instead (D-093)',
        ).toEqual([]);
    });
});
